using namespace std;

vector<pair<int,int>> merge_intervals(vector<pair<int,int>> intervals) {
    if (intervals.empty()) {
        return {};
    }

    // Sort intervals by start time
    sort(intervals.begin(), intervals.end(), [](const pair<int,int>& a, const pair<int,int>& b) {
        return a.first < b.first;
    });

    vector<pair<int,int>> merged;
    merged.push_back(intervals[0]);

    for (size_t i = 1; i < intervals.size(); ++i) {
        auto& last = merged.back();
        const auto& current = intervals[i];

        // If current interval overlaps or touches the last merged interval
        if (current.first <= last.second) {
            // Merge by extending the end if needed
            last.second = max(last.second, current.second);
        } else {
            // No overlap, add new interval
            merged.push_back(current);
        }
    }

    return merged;
}
