def eval_expr(expr: str) -> int:
    """
    Evaluate an integer arithmetic expression with +, -, *, /, parentheses.
    Division truncates toward zero.
    """
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch == ' ':
            i += 1
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        elif ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            raise ValueError(f"Unexpected character: {ch}")

    pos = [0]  # mutable index

    def parse_expr():
        """Parse addition and subtraction."""
        result = parse_term()
        while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
            op = tokens[pos[0]]
            pos[0] += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        """Parse multiplication and division."""
        result = parse_factor()
        while pos[0] < len(tokens) and tokens[pos[0]] in ('*', '/'):
            op = tokens[pos[0]]
            pos[0] += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                # Truncate toward zero
                if result * right < 0:
                    result = -((-result) // right) if result < 0 else -(result // (-right))
                else:
                    result = result // right
        return result

    def parse_factor():
        """Parse a number or parenthesized expression, handling unary minus/plus."""
        if pos[0] >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[pos[0]]

        if token == '(':
            pos[0] += 1
            result = parse_expr()
            if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
                raise ValueError("Missing closing parenthesis")
            pos[0] += 1
            return result
        elif token == '-':
            pos[0] += 1
            return -parse_factor()
        elif token == '+':
            pos[0] += 1
            return parse_factor()
        elif isinstance(token, int):
            pos[0] += 1
            return token
        else:
            raise ValueError(f"Unexpected token: {token}")

    result = parse_expr()
    return result
